DELETE FROM reminders;
DELETE FROM attendees;
DELETE FROM events;
DELETE FROM calendars;
DELETE FROM _counters;
UPDATE events
SET summary = CASE CAST(substr(event_id,-4) AS INTEGER) % 7
      WHEN 0 THEN 'Inherited IRA custodian document review'
      WHEN 1 THEN 'CPA beneficiary and withholding work session'
      WHEN 2 THEN 'Household liquidity and card due-date review'
      WHEN 3 THEN 'Estate reserve authorization check'
      WHEN 4 THEN 'Beneficiary distribution scenario review'
      WHEN 5 THEN 'Receipt and executor-approval archive'
      ELSE 'Official-source and calendar refresh'
    END || ' · ' || substr(start_dt,1,10),
    description = CASE CAST(substr(event_id,-4) AS INTEGER) % 7
      WHEN 0 THEN 'Review beneficiary registration, date-of-death records, distribution election prerequisites, and custodian processing status.'
      WHEN 1 THEN 'Separate verified tax facts, withholding estimates, year-of-death questions, and the next CPA follow-up.'
      WHEN 2 THEN 'Reconcile checking, bill-pay, both cards, pending payments, and the next fourteen days of ordinary cash needs.'
      WHEN 3 THEN 'Confirm that the estate reserve remains restricted and record any request that lacks Leah and counsel approval.'
      WHEN 4 THEN 'Compare no-distribution, limited-distribution, and later-distribution scenarios without placing a trade or election.'
      WHEN 5 THEN 'Match funeral or estate reimbursement requests to receipts, executor authority, payee, amount, and payment status.'
      ELSE 'Recheck IRS beneficiary guidance, estimated-tax dates, source retrieval date, and account-specific custodian instructions.'
    END,
    location = CASE CAST(substr(event_id,-4) AS INTEGER) % 3 WHEN 0 THEN 'Northstar Custody call' WHEN 1 THEN 'CPA video meeting' ELSE 'Leah finance calendar' END
WHERE event_id LIKE 'evt_iirtg_%';
